class Solution:
    def nextGeneration(self, board: List[List[int]]) -> List[List[int]]:
        old = [row[:] for row in board]
        m, n = len(old), len(old[0])
        for r in range(m):
            for c in range(n):
                live = 0
                for rr in range(max(0, r - 1), min(m, r + 2)):
                    for cc in range(max(0, c - 1), min(n, c + 2)):
                        live += old[rr][cc]
                live -= old[r][c]
                board[r][c] = 1 if live == 3 or (live == 2 and old[r][c]) else 0
        return board

