class Solution {
    public int[][] nextGeneration(int[][] board) {
        int m = board.length, n = board[0].length;
        int[][] old = new int[m][];
        for (int r = 0; r < m; r++) old[r] = board[r].clone();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int live = 0;
                for (int rr = Math.max(0, r - 1); rr <= Math.min(m - 1, r + 1); rr++)
                    for (int cc = Math.max(0, c - 1); cc <= Math.min(n - 1, c + 1); cc++)
                        live += old[rr][cc];
                live -= old[r][c];
                board[r][c] = (live == 3 || (live == 2 && old[r][c] == 1)) ? 1 : 0;
            }
        }
        return board;
    }
}

