class Solution {
    public int[][] nextGeneration(int[][] board) {
        int m = board.length, n = board[0].length;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int live = 0;
                for (int rr = Math.max(0, r - 1); rr <= Math.min(m - 1, r + 1); rr++)
                    for (int cc = Math.max(0, c - 1); cc <= Math.min(n - 1, c + 1); cc++)
                        live += board[rr][cc] & 1;
                live -= board[r][c] & 1;
                if (live == 3 || (live == 2 && (board[r][c] & 1) == 1)) board[r][c] |= 2;
            }
        }
        for (int[] row : board)
            for (int c = 0; c < n; c++) row[c] >>= 1;
        return board;
    }
}

